from bioblend.galaxy import GalaxyInstance
key=open(os.environ['GALAXY_API_KEY_FILE']).read().strip()
gi=GalaxyInstance('https://usegalaxy.org', key=key)
hist_id='bbd44e69cb8906b549310bbc6cde1a9d'
tid='toolshed.g2.bx.psu.edu/repos/iuc/ncbi_datasets/datasets_download_gene/18.33.1+galaxy0'
inputs={
 'query': {
   'subcommand': {
     'download_by': 'accession',
     'text_or_file': {
       'text_or_file': 'file',
       'inputfile': {'src':'hda','id':'f9cad7b01a472135023e12655ba540a9'}
     },
     'taxon_filter': ''
   }
 },
 'filters': {'fasta_filter_cond': {'fasta_filter_select': ''}},
 'file_choices': {
   'kingdom_cond': {
     'kingdom_sel': 'gene',
     'report_columns': ['gene-id','ensembl-geneids','symbol','description','omim-ids'],
     'include': ['gene']
   },
   'decompress': False
 }
}
print('submitting...')
res=gi.tools.run_tool(hist_id, tid, inputs)
print(json.dumps(res)[:3000])
if 'jobs' in res and res['jobs']:
    job=res['jobs'][0]
    state=gi.jobs.wait_for_job(job['id'], maxwait=300, interval=5)
    print('final_state', state['state'])
    print(json.dumps(state)[:2000])
elif 'outputs' in res:
    print('outputs', json.dumps(res['outputs'])[:3000])
PY"

